  &DefaultButton;




function dir$dmbh(p){
    this.constructor(p);
	document._dir = p;
}
dir$dmbh.prototype = new DirEvent();
dir$dmbh.prototype.afterInit = function() {
  	var p = this._dir;
  	if (p.options.action == 'NEW') p.request('LoadBHCode','',['ma_bh']);
  	setTimeout(function() {		
		setImages('img_ximage1', 'ximage1', p);
	}, 500);
	dir$LoadDataProduct(p);
	dir$LoadDataCustom(p);
}

dir$dmbh.prototype.formFieldValueChange = function (o, cF, v) {
  var p = this._dir;

  switch (cF){
	case 'model':
		dir$LoadDataProduct(p);
		dir$dmbhLoadNgayBh(p);
		break;
	case 'ma_kh':
		dir$LoadDataCustom(p);
		break;
	case 'ngay_bh':
		dir$dmbhLoadNgayBh(p);
		break;
    default:
      break;
  }
}
function dir$dmbhLoadNgayBh(p) {
	setTimeout(function () {	
		if (p.valForm('ngay_bh') != null && p.valForm('so_ngay_bh') >= 0) {
			var startDate = new Date(p.valForm('ngay_bh'));
			startDate.setMonth(startDate.getMonth() + p.valForm('so_ngay_bh'));
			p.valForm('ngay_hbh', startDate, true);
			console.log(startDate);
		}
	}, 500);
}
function browseServer(value, src) {
	var p = document._dir;
	var finder = new CKFinder();
	finder.selectActionFunction = function (url) {
		p.valForm(value, url, true);
		document.getElementById(src).src = url;
	};
	finder.popup();
}
function setImages(id, name, p) {
	$('#' + id).attr("src", p.valForm(name));
}
function dir$LoadDataProduct(p) {
	if (p.options.action == 'NEW' || p.options.action == 'EDIT' || p.options.action == 'VIEW')
	{
		if(p.valForm('model') != '') p.request('LoadInfoProduct','',['model']);
		else {
			p.valForm('ten_vt','',true)
			p.valForm('so_ngay_bh','',true)
		}
	}
}
function dir$LoadDataCustom(p) {
	if (p.options.action == 'NEW' || p.options.action == 'EDIT' || p.options.action == 'VIEW')
	{
		if(p.valForm('ma_kh') != '') p.request('LoadInfoCustom','',['ma_kh']);
		else {
			p.valForm('ten_kh','',true)
			p.valForm('dien_thoai','',true)
		}
	}
}








