-- Update data xstatus trong dmmodelvt 
Update a set a.xstatus2 = 0 from dmmodelvt a where EXISTS (select 1 from @@table b where a.ma_vt =  b.model and a.ma_model = b.series)








-- Update data xstatus trong dmmodelvt 
IF @status = 1 update a set a.xstatus2 = 5 from dmmodelvt a where EXISTS (select 1 from @@table b where a.ma_vt =  b.model and a.ma_model = b.series)
